create extension if not exists pgcrypto;
create type public.validation_status as enum ('not_started','draft','pending','ready','validated');
create table public.participants(id uuid primary key default gen_random_uuid(),auth_user_id uuid not null default auth.uid(),name text not null,executive text not null,role_area text,created_at timestamptz not null default now());
create table public.projects(id uuid primary key default gen_random_uuid(),name text not null,executive text,axis text,objective text,primary_area text,secondary_area text,provenance text not null default 'Pendente de informação',divergence text,original_data jsonb not null default '{}',created_at timestamptz not null default now());
create unique index projects_name_normalized on public.projects(lower(trim(name)));
create table public.planning_records(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects on delete cascade,author_id uuid not null references auth.users,goal text,actual_2025 numeric,target_2026 numeric,target_2027 numeric,target_2028 numeric,unit text,indicator text,metric text,frequency text,owner text,notes text,status public.validation_status not null default 'draft',updated_at timestamptz not null default now());
create table public.initiatives(id uuid primary key default gen_random_uuid(),record_id uuid not null references public.planning_records on delete cascade,description text not null,position int not null default 0);
create table public.change_history(id bigint generated always as identity primary key,record_id uuid not null references public.planning_records on delete cascade,author_id uuid not null references auth.users,content jsonb not null,created_at timestamptz not null default now());
alter table public.participants enable row level security;alter table public.projects enable row level security;alter table public.planning_records enable row level security;alter table public.initiatives enable row level security;alter table public.change_history enable row level security;
create policy "portfolio readable by workshop participants" on public.projects for select to authenticated using(true);
create policy "participant owns identity" on public.participants for all to authenticated using((select auth.uid())=auth_user_id) with check((select auth.uid())=auth_user_id);
create policy "author owns planning record" on public.planning_records for all to authenticated using((select auth.uid())=author_id) with check((select auth.uid())=author_id);
create policy "author manages initiatives" on public.initiatives for all to authenticated using(exists(select 1 from public.planning_records r where r.id=record_id and r.author_id=(select auth.uid()))) with check(exists(select 1 from public.planning_records r where r.id=record_id and r.author_id=(select auth.uid())));
create policy "author reads history" on public.change_history for select to authenticated using(author_id=(select auth.uid()));create policy "author inserts history" on public.change_history for insert to authenticated with check(author_id=(select auth.uid()));
grant select on public.projects to authenticated;grant select,insert,update,delete on public.participants,public.planning_records,public.initiatives to authenticated;grant select,insert on public.change_history to authenticated;
